// active_read_guards <= reader_bits: derive from old invariant
// The old invariant: active_read_guards <= reader_bits
// new_active = old_active - 1 <= reader_bits - 1 <= new_reader_bits
let ghost new_active: int = MAX_READER_U64 as int - g.read_guard_token.left().frac();
let ghost old_active: int = MAX_READER_U64 as int - old_pool_frac;
assert(new_active == old_active - 1);
// old_active <= old_reader_bits (from old invariant)
// new_reader_bits >= old_reader_bits - READER (from lemma_consts_properties_prev_next)
// new_active = old_active - 1 <= old_reader_bits - 1 <= new_reader_bits
let ghost old_has_max_bit: bool = (prev_usize & MAX_READER) != 0;
let ghost new_has_max_bit: bool = (next_usize & MAX_READER) != 0;
let ghost old_reader_bits: int = if old_has_max_bit { MAX_READER as int } else { (prev_usize & READER_MASK) as int };
let ghost new_reader_bits: int = if new_has_max_bit { MAX_READER as int } else { (next_usize & READER_MASK) as int };
assert(new_active <= new_reader_bits) by {
    if prev_usize & READER_MASK != 0 {
        // When prev & READER_MASK != 0, the lemma gives us next & READER_MASK = prev & READER_MASK - READER
        // and next & MAX_READER == prev & MAX_READER (unchanged)
        // So new_has_max_bit == old_has_max_bit
        assert(new_has_max_bit == old_has_max_bit);
        if old_has_max_bit {
            assert(new_reader_bits == MAX_READER as int);
            assert(old_active <= MAX_READER as int); // from old invariant
            assert(new_active <= MAX_READER as int);
        } else {
            assert(new_reader_bits == old_reader_bits - READER as int);
            assert(old_active <= old_reader_bits); // from old invariant
            assert(new_active <= new_reader_bits);
        }
    } else {
        // prev & READER_MASK == 0, so prev & MAX_READER != 0 (since prev & MAX_READER_MASK != 0)
        // prev & MAX_READER_MASK = MAX_READER (only MAX_READER bit set)
        // After subtracting READER=1: next & MAX_READER_MASK = MAX_READER - 1 = READER_MASK
        // So next & MAX_READER == 0 (no carry into MAX_READER bit)
        // new_reader_bits = next & READER_MASK
        // From old invariant: old_active <= old_reader_bits = MAX_READER
        // new_active = old_active - 1 <= MAX_READER - 1 = READER_MASK = next & READER_MASK = new_reader_bits
        assert(prev_usize & MAX_READER != 0); // from prev & MAX_READER_MASK != 0 and READER_MASK == 0
        assert(!new_has_max_bit);
        assert(old_reader_bits == MAX_READER as int);
        assert(old_active <= MAX_READER as int); // from old invariant
        assert(new_active == old_active - 1 <= MAX_READER as int - 1);
        // next & READER_MASK: from lemma, since prev & MAX_READER_MASK != 0 case doesn't mention READER_MASK
        // But next = prev - 1 and prev & READER_MASK = 0 and prev & MAX_READER != 0
        // So next & READER_MASK = READER_MASK (all low bits become 1... not quite)
        // Actually: MAX_READER - 1 = READER_MASK
        // prev = (...MAX_READER_bit...) | 0 = prev with some upper bits + MAX_READER bit
        // next = prev - 1: subtracting 1 from the MAX_READER bit (no carry from below since READER_MASK bits = 0)
        // So next = prev - 1 = (prev & ~MAX_READER_MASK) | (MAX_READER - 1) = (prev & ~MAX_READER_MASK) | READER_MASK
        // next & READER_MASK = READER_MASK
        // new_reader_bits = READER_MASK
        // MAX_READER - 1 = READER_MASK
        // new_active <= MAX_READER - 1 = READER_MASK = new_reader_bits ✓
    }
};

