assert(new_active == old_active - 1);
// From old invariant: old_active <= old_reader_bits
// new_active = old_active - 1 <= old_reader_bits - 1 <= new_reader_bits
// Because decreasing by READER from the value decreases reader_bits by at most READER
let ghost old_has_max_bit: bool = (prev_usize & MAX_READER) != 0;
let ghost new_has_max_bit: bool = (next_usize & MAX_READER) != 0;
let ghost old_reader_bits: int = if old_has_max_bit { MAX_READER as int } else { (prev_usize & READER_MASK) as int };
let ghost new_reader_bits: int = if new_has_max_bit { MAX_READER as int } else { (next_usize & READER_MASK) as int };
assert(new_active <= new_reader_bits) by {
    if prev_usize & READER_MASK != 0 {
        // From lemma: next & READER_MASK = prev & READER_MASK - READER
        // and next & MAX_READER = prev & MAX_READER (unchanged)
        assert(new_has_max_bit == old_has_max_bit);
        if old_has_max_bit {
            assert(new_reader_bits == MAX_READER as int);
            assert(old_active <= MAX_READER as int); // from old invariant
        } else {
            assert(new_reader_bits == old_reader_bits - READER as int);
            assert(old_active <= old_reader_bits); // from old invariant
        }
    } else {
        // prev & READER_MASK == 0 and prev & MAX_READER_MASK != 0
        // => prev & MAX_READER != 0
        // From lemma: next & MAX_READER_MASK = (prev & MAX_READER_MASK) - READER
