// active_read_guards <= reader_bits: prove from old invariant
// We need: new_active <= new_reader_bits
// where new_active = old_active - 1 and new_reader_bits changes based on bit transitions
let ghost new_active: int = MAX_READER_U64 as int - g.read_guard_token.left().frac();
let ghost old_active: int = MAX_READER_U64 as int - old_pool_frac;
assert(new_active == old_active - 1);
let ghost old_has_max_bit: bool = (prev_usize & MAX_READER) != 0;
let ghost new_has_max_bit: bool = (next_usize & MAX_READER) != 0;
let ghost old_reader_bits: int = if old_has_max_bit { MAX_READER as int } else { (prev_usize & READER_MASK) as int };
let ghost new_reader_bits: int = if new_has_max_bit { MAX_READER as int } else { (next_usize & READER_MASK) as int };
assert(new_active <= new_reader_bits) by {
    if prev_usize & READER_MASK != 0 {
        // From lemma: next & READER_MASK = prev & READER_MASK - READER
        // and next & MAX_READER = prev & MAX_READER (unchanged)
        assert(new_has_max_bit == old_has_max_bit);
        assert(old_active <= old_reader_bits); // from old invariant
        if old_has_max_bit {
            assert(new_reader_bits == MAX_READER as int);
            assert(new_active <= MAX_READER as int);
        } else {
            // new_reader_bits = prev & READER_MASK - 1 = old_reader_bits - 1
            assert(new_reader_bits == old_reader_bits - READER as int);
            assert(new_active == old_active - READER as int);
        }
    } else {
        // prev & READER_MASK == 0, prev & MAX_READER != 0
        assert(old_has_max_bit);
        assert(old_reader_bits == MAX_READER as int);
        assert(old_active <= MAX_READER as int); // from old invariant
        // next & MAX_READER_MASK = MAX_READER - 1 (from lemma)
        assert((next_usize & MAX_READER_MASK) as int == MAX_READER as int - READER as int);
        // next & MAX_READER = 0 because (MAX_READER - 1) has no MAX_READER bit
        // This is a property of MAX_READER being a power of 2
        // We use: next & MAX_READER_MASK = MAX_READER - 1
        // MAX_READER - 1 < MAX_READER, so MAX_READER bit cannot be set
        assert(!new_has_max_bit) by {
            // MAX_READER is a power of 2 > 0
            // MAX_READER - 1 < MAX_READER, so MAX_READER bit clear
            assert(MAX_READER as int > 0);
            assert((next_usize & MAX_READER_MASK) as int < MAX_READER as int);
        };
        // new_reader_bits = next & READER_MASK
        // From next & MAX_READER_MASK = MAX_READER - 1 and next & MAX_READER = 0:
        // next & READER_MASK = next & MAX_READER_MASK (since MAX_READER bit = 0)
        // = MAX_READER - 1
        assert(new_reader_bits == (next_usize & READER_MASK) as int);
        // next & READER_MASK = next & MAX_READER_MASK = MAX_READER - 1
        assert((next_usize & READER_MASK) as int == MAX_READER as int - READER as int) by {
            // next & MAX_READER_MASK = MAX_READER - 1
            // next & MAX_READER = 0
            // MAX_READER_MASK = MAX_READER | READER_MASK and MAX_READER & READER_MASK = 0
            // So next & READER_MASK = (next & MAX_READER_MASK) - (next & MAX_READER)
            //                       = MAX_READER - 1 - 0 = MAX_READER - 1
            assert(READER as int == 1);
        };
        assert(new_reader_bits == MAX_READER as int - 1);
        assert(new_active <= MAX_READER as int - 1);
    }
};

